/**
 * Layout Service
 * 
 * API client for dashboard layout management.
 */

import { Layouts } from '../config/defaultDashboardLayout';

const API_BASE = process.env.REACT_APP_API_URL ||
    (typeof window !== 'undefined'
        ? `${window.location.protocol}//${window.location.hostname}:3001`
        : 'http://localhost:3001');

export interface LayoutResponse {
    success: boolean;
    data?: {
        layoutKey: string;
        layouts: Layouts;
        updatedAt: string | null;
        updatedBy: { id: number; displayName: string } | null;
        isDefault: boolean;
    };
    error?: string;
}

export interface SaveLayoutResponse {
    success: boolean;
    data?: {
        layoutKey: string;
        layouts: Layouts;
        updatedAt: string;
        updatedBy: { id: number; displayName: string } | null;
    };
    message?: string;
    error?: string;
}

/**
 * Get layout from backend
 */
export async function getLayout(layoutKey: string = 'default'): Promise<LayoutResponse> {
    try {
        const response = await fetch(`${API_BASE}/api/layout/${layoutKey}`);
        return response.json();
    } catch (error) {
        console.error('Failed to fetch layout:', error);
        return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to fetch layout'
        };
    }
}

/**
 * Save layout to backend (admin only)
 */
export async function saveLayout(
    layoutKey: string,
    layouts: Layouts,
    token: string
): Promise<SaveLayoutResponse> {
    try {
        const response = await fetch(`${API_BASE}/api/layout/${layoutKey}`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify({ layouts })
        });
        return response.json();
    } catch (error) {
        console.error('Failed to save layout:', error);
        return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to save layout'
        };
    }
}

/**
 * Reset layout to default (admin only)
 */
export async function resetLayout(
    layoutKey: string,
    token: string
): Promise<SaveLayoutResponse> {
    try {
        const response = await fetch(`${API_BASE}/api/layout/${layoutKey}/reset`, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`
            }
        });
        return response.json();
    } catch (error) {
        console.error('Failed to reset layout:', error);
        return {
            success: false,
            error: error instanceof Error ? error.message : 'Failed to reset layout'
        };
    }
}
