/**
 * User Service
 * 
 * API client for user management.
 */

const API_BASE = process.env.REACT_APP_API_URL ||
    (typeof window !== 'undefined'
        ? `${window.location.protocol}//${window.location.hostname}:3001`
        : 'http://localhost:3001');

export interface User {
    id: number;
    username: string;
    email: string | null;
    display_name: string | null;
    full_name: string | null;
    phone_number: string | null;
    role: 'admin' | 'user' | 'viewer';
    is_active: boolean;
    is_verified: boolean;
    created_at: string;
    updated_at: string;
}

export interface UserListResponse {
    success: boolean;
    data?: User[];
    meta?: {
        total: number;
        limit: number;
        offset: number;
    };
    error?: string;
}

export interface UserResponse {
    success: boolean;
    data?: User;
    message?: string;
    error?: string;
}

export interface CreateUserData {
    username: string;
    email?: string;
    password: string;
    display_name?: string;
    full_name?: string;
    phone_number?: string;
    role?: 'admin' | 'user' | 'viewer';
}

export interface UpdateUserData {
    email?: string;
    display_name?: string;
    full_name?: string;
    phone_number?: string;
    role?: 'admin' | 'user' | 'viewer';
    is_active?: boolean;
    is_verified?: boolean;
}

function getAuthHeader(token: string): HeadersInit {
    return {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
    };
}

/**
 * Get all users (admin only)
 */
export async function getAllUsers(token: string, options: {
    includeInactive?: boolean;
    limit?: number;
    offset?: number;
} = {}): Promise<UserListResponse> {
    try {
        const params = new URLSearchParams();
        if (options.includeInactive) params.set('includeInactive', 'true');
        if (options.limit) params.set('limit', String(options.limit));
        if (options.offset) params.set('offset', String(options.offset));

        const response = await fetch(`${API_BASE}/api/users?${params}`, {
            headers: getAuthHeader(token)
        });
        return response.json();
    } catch (error) {
        console.error('Failed to fetch users:', error);
        return { success: false, error: 'Failed to fetch users' };
    }
}

/**
 * Get current user profile
 */
export async function getMyProfile(token: string): Promise<UserResponse> {
    try {
        const response = await fetch(`${API_BASE}/api/users/me`, {
            headers: getAuthHeader(token)
        });
        return response.json();
    } catch (error) {
        console.error('Failed to fetch profile:', error);
        return { success: false, error: 'Failed to fetch profile' };
    }
}

/**
 * Update current user profile
 */
export async function updateMyProfile(token: string, data: UpdateUserData): Promise<UserResponse> {
    try {
        const response = await fetch(`${API_BASE}/api/users/me`, {
            method: 'PUT',
            headers: getAuthHeader(token),
            body: JSON.stringify(data)
        });
        return response.json();
    } catch (error) {
        console.error('Failed to update profile:', error);
        return { success: false, error: 'Failed to update profile' };
    }
}

