/**
 * Authentication Service
 * 
 * Handles API calls for login, logout, and user management.
 */

// Use same host as frontend but on port 3001 for backend API
const API_BASE = process.env.REACT_APP_API_URL ||
    (typeof window !== 'undefined'
        ? `${window.location.protocol}//${window.location.hostname}:3001`
        : 'http://localhost:3001');

export interface User {
    id: number;
    username: string;
    displayName: string;
    role: 'admin' | 'user' | 'viewer';
}

export interface LoginResponse {
    success: boolean;
    data?: {
        token: string;
        expiresAt: string;
        user: User;
    };
    error?: string;
}

export interface AuthSession {
    id: number;
    ipAddress: string;
    userAgent: string;
    createdAt: string;
    expiresAt: string;
    current: boolean;
}

/**
 * Login with username and password
 */
export async function login(username: string, password: string): Promise<LoginResponse> {
    const response = await fetch(`${API_BASE}/api/auth/login`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username, password }),
    });

    return response.json();
}

/**
 * Logout current session
 */
export async function logout(token: string): Promise<{ success: boolean }> {
    const response = await fetch(`${API_BASE}/api/auth/logout`, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${token}`,
        },
    });

    return response.json();
}

/**
 * Get current user info
 */
export async function getCurrentUser(token: string): Promise<{ success: boolean; data?: User }> {
    const response = await fetch(`${API_BASE}/api/auth/me`, {
        headers: {
            'Authorization': `Bearer ${token}`,
        },
    });

    return response.json();
}

/**
 * Get active sessions
 */
export async function getSessions(token: string): Promise<{ success: boolean; data?: AuthSession[] }> {
    const response = await fetch(`${API_BASE}/api/auth/sessions`, {
        headers: {
            'Authorization': `Bearer ${token}`,
        },
    });

    return response.json();
}

/**
 * Token storage helpers
 */
const TOKEN_KEY = 'auth_token';
const USER_KEY = 'auth_user';

export function saveAuthData(token: string, user: User): void {
    localStorage.setItem(TOKEN_KEY, token);
    localStorage.setItem(USER_KEY, JSON.stringify(user));
}

export function getStoredToken(): string | null {
    return localStorage.getItem(TOKEN_KEY);
}

export function getStoredUser(): User | null {
    const userStr = localStorage.getItem(USER_KEY);
    if (userStr) {
        try {
            return JSON.parse(userStr);
        } catch {
            return null;
        }
    }
    return null;
}

export function clearAuthData(): void {
    localStorage.removeItem(TOKEN_KEY);
    localStorage.removeItem(USER_KEY);
}
