import React, { useState, useEffect, useRef } from 'react';
import { X, Calendar, ChevronLeft, ChevronRight, Check, ChevronDown } from 'lucide-react';
import { useTimeRange } from '../context/TimeRangeContext';
import { useTheme } from './AppShell';

// Quick preset options
const PRESETS = [
    { label: 'Today', days: 0, type: 'today' },
    { label: 'Yesterday', days: 1, type: 'yesterday' },
    { label: 'Last 7 Days', days: 7, type: 'days' },
    { label: 'Last 30 Days', days: 30, type: 'days' },
    { label: 'This Week', days: 0, type: 'thisWeek' },
    { label: 'This Month', days: 0, type: 'thisMonth' },
] as const;

const DAYS = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

interface DateRangePickerProps {
    className?: string;
}

const DateRangePicker: React.FC<DateRangePickerProps> = ({ className = '' }) => {
    const { isCalendarOpen, closeCalendar, setCustomRange, setMode } = useTimeRange();
    const { currentTheme, darkMode } = useTheme();
    const containerRef = useRef<HTMLDivElement>(null);

    // Calendar state
    const [currentMonth, setCurrentMonth] = useState(new Date());
    const [startDate, setStartDate] = useState<Date | null>(null);
    const [endDate, setEndDate] = useState<Date | null>(null);
    const [selecting, setSelecting] = useState<'start' | 'end'>('start');

    // Reset selection when calendar opens
    useEffect(() => {
        if (isCalendarOpen) {
            setStartDate(null);
            setEndDate(null);
            setSelecting('start');
            setCurrentMonth(new Date());
        }
    }, [isCalendarOpen]);

    // Handle outside click
    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                closeCalendar();
            }
        };

        if (isCalendarOpen) {
            // Delay adding listener to prevent immediate close
            const timer = setTimeout(() => {
                document.addEventListener('mousedown', handleClickOutside);
            }, 100);
            return () => {
                clearTimeout(timer);
                document.removeEventListener('mousedown', handleClickOutside);
            };
        }
    }, [isCalendarOpen, closeCalendar]);

    const prevMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
    };

    const nextMonth = () => {
        setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));
    };

    const handleDateClick = (date: Date) => {
        if (selecting === 'start') {
            setStartDate(date);
            setEndDate(null);
            setSelecting('end');
        } else {
            if (startDate && date < startDate) {
                setStartDate(date);
                setEndDate(startDate);
            } else {
                setEndDate(date);
            }
            setSelecting('start');
        }
    };

    const handlePresetClick = (preset: typeof PRESETS[number]) => {
        const today = new Date();
        today.setHours(23, 59, 59, 999);
        let start: Date;
        let end = new Date(today);

        switch (preset.type) {
            case 'today':
                start = new Date(today);
                start.setHours(0, 0, 0, 0);
                break;
            case 'yesterday':
                start = new Date(today);
                start.setDate(start.getDate() - 1);
                start.setHours(0, 0, 0, 0);
                end = new Date(start);
                end.setHours(23, 59, 59, 999);
                break;
            case 'days':
                start = new Date(today);
                start.setDate(start.getDate() - preset.days);
                start.setHours(0, 0, 0, 0);
                break;
            case 'thisWeek':
                start = new Date(today);
                start.setDate(start.getDate() - start.getDay());
                start.setHours(0, 0, 0, 0);
                break;
            case 'thisMonth':
                start = new Date(today.getFullYear(), today.getMonth(), 1);
                start.setHours(0, 0, 0, 0);
                break;
            default:
                start = new Date(today);
        }

        setStartDate(start);
        setEndDate(end);

        // Auto-apply after preset selection
        setCustomRange({ start, end });
        setMode('custom');
        closeCalendar();
    };

    const handleApply = () => {
        if (startDate && endDate) {
            setCustomRange({ start: startDate, end: endDate });
            setMode('custom');
            closeCalendar();
        }
    };

    const getDaysInMonth = (date: Date) => {
        return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    };

    const getFirstDayOfMonth = (date: Date) => {
        return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
    };

    const isInRange = (date: Date) => {
        if (!startDate || !endDate) return false;
        return date >= startDate && date <= endDate;
    };

    const isStartDate = (date: Date) => {
        return startDate && date.toDateString() === startDate.toDateString();
    };

    const isEndDate = (date: Date) => {
        return endDate && date.toDateString() === endDate.toDateString();
    };

    const renderCalendar = () => {
        const daysInMonth = getDaysInMonth(currentMonth);
        const firstDay = getFirstDayOfMonth(currentMonth);
        const days = [];

        // Empty cells for days before first day of month
        for (let i = 0; i < firstDay; i++) {
            days.push(<div key={`empty-${i}`} className="h-8" />);
        }

        // Days of the month
        for (let day = 1; day <= daysInMonth; day++) {
            const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
            const isStart = isStartDate(date);
            const isEnd = isEndDate(date);
            const inRange = isInRange(date);
            const isToday = date.toDateString() === new Date().toDateString();

            days.push(
                <button
                    key={day}
                    onClick={() => handleDateClick(date)}
                    className={`
                        h-8 w-8 rounded-full flex items-center justify-center text-xs font-medium transition-all
                        ${isStart || isEnd
                            ? `${currentTheme.accent} text-white shadow-md`
                            : inRange
                                ? `${currentTheme.accentLight} ${currentTheme.text}`
                                : 'hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300'}
                        ${isToday && !isStart && !isEnd ? 'ring-1 ring-gray-300 dark:ring-gray-600' : ''}
                    `}
                >
                    {day}
                </button>
            );
        }

        return days;
    };

    if (!isCalendarOpen) return null;

    // Inline Calendar (appears below the time selector)
    return (
        <div
            ref={containerRef}
            className={`
                w-full bg-white/95 dark:bg-gray-800/95 backdrop-blur-sm
                border-b border-gray-200 dark:border-gray-700
                shadow-lg animate-fade-in
                ${className}
            `}
        >
            <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
                <div className="flex flex-col lg:flex-row gap-4 lg:gap-6">

                    {/* Quick Presets Column */}
                    <div className="lg:w-48 shrink-0">
                        <div className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                            Quick Select
                        </div>
                        <div className="flex flex-wrap lg:flex-col gap-1.5">
                            {PRESETS.map((preset) => (
                                <button
                                    key={preset.label}
                                    onClick={() => handlePresetClick(preset)}
                                    className={`
                                        px-3 py-1.5 text-sm rounded-lg border transition-all text-left
                                        border-gray-200 dark:border-gray-600 
                                        text-gray-700 dark:text-gray-300
                                        hover:${currentTheme.accent} hover:text-white hover:border-transparent
                                        hover:shadow-md
                                    `}
                                >
                                    {preset.label}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Calendar */}
                    <div className="flex-1 min-w-0">
                        <div className="bg-gray-50 dark:bg-gray-900/50 rounded-xl p-4">
                            {/* Month Navigation */}
                            <div className="flex items-center justify-between mb-3">
                                <button
                                    onClick={prevMonth}
                                    className="p-1.5 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
                                >
                                    <ChevronLeft className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                                </button>
                                <span className="font-semibold text-sm text-gray-900 dark:text-white">
                                    {MONTHS[currentMonth.getMonth()]} {currentMonth.getFullYear()}
                                </span>
                                <button
                                    onClick={nextMonth}
                                    className="p-1.5 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
                                >
                                    <ChevronRight className="w-4 h-4 text-gray-600 dark:text-gray-400" />
                                </button>
                            </div>

                            {/* Day Headers */}
                            <div className="grid grid-cols-7 gap-1 mb-1">
                                {DAYS.map(day => (
                                    <div key={day} className="h-8 flex items-center justify-center text-xs font-medium text-gray-400 dark:text-gray-500">
                                        {day}
                                    </div>
                                ))}
                            </div>

                            {/* Calendar Grid */}
                            <div className="grid grid-cols-7 gap-1">
                                {renderCalendar()}
                            </div>
                        </div>
                    </div>

                    {/* Selected Range & Actions */}
                    <div className="lg:w-56 shrink-0 flex flex-col justify-between">
                        <div>
                            <div className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-2">
                                Selected Range
                            </div>
                            <div className={`p-3 rounded-lg border ${currentTheme.border} ${currentTheme.accentLight}`}>
                                {startDate && endDate ? (
                                    <div className="space-y-1">
                                        <div className="text-xs text-gray-500 dark:text-gray-400">From</div>
                                        <div className={`font-semibold ${currentTheme.text}`}>
                                            {startDate.toLocaleDateString('th-TH', { weekday: 'short', day: 'numeric', month: 'short' })}
                                        </div>
                                        <div className="text-xs text-gray-500 dark:text-gray-400 mt-2">To</div>
                                        <div className={`font-semibold ${currentTheme.text}`}>
                                            {endDate.toLocaleDateString('th-TH', { weekday: 'short', day: 'numeric', month: 'short' })}
                                        </div>
                                    </div>
                                ) : startDate ? (
                                    <div className="text-sm text-gray-600 dark:text-gray-400">
                                        <span className="font-medium">{startDate.toLocaleDateString('th-TH', { day: 'numeric', month: 'short' })}</span>
                                        <span className="mx-2">→</span>
                                        <span className="text-gray-400">Select end date</span>
                                    </div>
                                ) : (
                                    <div className="text-sm text-gray-500 dark:text-gray-400">
                                        Click on calendar to select start date
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Action Buttons */}
                        <div className="flex gap-2 mt-4">
                            <button
                                onClick={closeCalendar}
                                className="flex-1 px-3 py-2 text-sm font-medium text-gray-600 dark:text-gray-400 
                                    hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleApply}
                                disabled={!startDate || !endDate}
                                className={`
                                    flex-1 px-3 py-2 text-sm font-medium text-white rounded-lg 
                                    flex items-center justify-center gap-1.5 transition-all
                                    ${startDate && endDate
                                        ? `${currentTheme.accent} ${currentTheme.accentHover} shadow-md`
                                        : 'bg-gray-300 dark:bg-gray-600 cursor-not-allowed'}
                                `}
                            >
                                <Check className="w-4 h-4" />
                                Apply
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DateRangePicker;
