import React, { useState, useEffect, useCallback, useRef } from 'react';

import FrequencyBlock from '../../components/FrequencyBlock';
import CurrentBlock from '../../components/CurrentBlock';
import PowerFactorBlock from '../../components/PowerFactorBlock';
import EnergyAccumulatedBlock from '../../components/EnergyAccumulatedBlock';
import ActivePowerBlock from '../../components/ActivePowerBlock';
import { InfluxProvider } from '../../context/InfluxContext';
import InfluxErrorNotification from '../../components/InfluxErrorNotification';
import { useWebSocket } from '../../context/WebSocketContext';
import { useLanguage } from '../../context/LanguageContext';
import EnergyCostBlock from '../../components/EnergyCostBlock';
import TimeRangeSummaryPanel from '../../components/TimeRangeSummaryPanel';
import StatisticsBlock from '../../components/StatisticsBlock';
import { DashboardLayoutProvider, useDashboardLayout } from '../../context/DashboardLayoutContext';
import EditModeToggle from '../../components/EditModeToggle';
import { LayoutItem, widgetConfig } from '../../config/defaultDashboardLayout';
import './DashboardPage.css';

// Widget component map
const widgetComponents: Record<string, { component: React.FC; title: string }> = {
  'energy-cost': { component: EnergyCostBlock, title: 'Energy Cost' },
  'active-power': { component: ActivePowerBlock, title: 'Active Power' },
  'energy-accumulated': { component: EnergyAccumulatedBlock, title: 'Energy Accumulated' },
  'frequency': { component: FrequencyBlock, title: 'Voltage' },
  'current': { component: CurrentBlock, title: 'Current' },
  'power-factor': { component: PowerFactorBlock, title: 'Power Factor' },
  'statistics': { component: StatisticsBlock, title: 'Statistics' },
};

// Resize handle type
type ResizeDirection = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw' | null;

// Inner component that uses the layout context
const DashboardContent: React.FC = () => {
  const { isConnected, lastUpdate } = useWebSocket();
  const { t } = useLanguage();
  const { layouts, isEditMode, isAdmin, isLoading, updateLayouts } = useDashboardLayout();
  const [currentTime, setCurrentTime] = useState(new Date());
  const [draggedWidget, setDraggedWidget] = useState<string | null>(null);
  const [showAddPanel, setShowAddPanel] = useState(false);
  const [selectedWidget, setSelectedWidget] = useState<string | null>(null);

  // Resize state
  const [resizing, setResizing] = useState<{
    widgetId: string;
    direction: ResizeDirection;
    startX: number;
    startY: number;
    startW: number;
    startH: number;
  } | null>(null);

  const containerRef = useRef<HTMLDivElement>(null);

  // Real-time clock effect
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Get current layout
  const currentLayout = layouts.lg;

  // Get hidden widgets (not in current layout)
  const hiddenWidgets = Object.keys(widgetComponents).filter(
    widgetId => !currentLayout.some(item => item.i === widgetId)
  );

  // Sort widgets by their position (y first, then x)
  const sortedWidgets = [...currentLayout].sort((a, b) => {
    if (a.y !== b.y) return a.y - b.y;
    return a.x - b.x;
  });

  // Helper function to update all layouts
  const updateAllLayouts = useCallback((newLayout: LayoutItem[]) => {
    updateLayouts({
      ...layouts,
      lg: newLayout,
      md: newLayout,
      sm: newLayout,
      xs: newLayout,
    });
  }, [layouts, updateLayouts]);

  // Handle drag start
  const handleDragStart = (e: React.DragEvent, widgetId: string) => {
    if (!isEditMode || !isAdmin || resizing) return;
    setDraggedWidget(widgetId);
    e.dataTransfer.effectAllowed = 'move';
  };

  // Handle drag over
  const handleDragOver = (e: React.DragEvent) => {
    if (!isEditMode || !isAdmin) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
  };

  // Handle drop (swap positions)
  const handleDrop = (e: React.DragEvent, targetWidgetId: string) => {
    if (!isEditMode || !isAdmin || !draggedWidget || draggedWidget === targetWidgetId) return;
    e.preventDefault();

    const newLayout = currentLayout.map(item => {
      if (item.i === draggedWidget) {
        const target = currentLayout.find(t => t.i === targetWidgetId);
        return target ? { ...item, x: target.x, y: target.y } : item;
      }
      if (item.i === targetWidgetId) {
        const source = currentLayout.find(s => s.i === draggedWidget);
        return source ? { ...item, x: source.x, y: source.y } : item;
      }
      return item;
    });

    updateAllLayouts(newLayout);
    setDraggedWidget(null);
  };

  // Handle delete widget
  const handleDeleteWidget = useCallback((widgetId: string) => {
    if (!isEditMode || !isAdmin) return;
    if (!window.confirm(`Remove "${widgetComponents[widgetId]?.title}" from dashboard?`)) return;

    const newLayout = currentLayout.filter(item => item.i !== widgetId);
    updateAllLayouts(newLayout);
    setSelectedWidget(null);
  }, [isEditMode, isAdmin, currentLayout, updateAllLayouts]);

  // Handle add widget
  const handleAddWidget = useCallback((widgetId: string) => {
    if (!isEditMode || !isAdmin) return;

    const config = widgetConfig[widgetId] || { minW: 1, minH: 1 };
    const maxY = currentLayout.reduce((max, item) => Math.max(max, item.y + item.h), 0);

    const newWidget: LayoutItem = {
      i: widgetId,
      x: 0,
      y: maxY,
      w: config.minW || 2,
      h: config.minH || 1,
      minW: config.minW,
      minH: config.minH,
    };

    updateAllLayouts([...currentLayout, newWidget]);
    setShowAddPanel(false);
  }, [isEditMode, isAdmin, currentLayout, updateAllLayouts]);

  // Handle move widget up
  const handleMoveUp = useCallback((widgetId: string) => {
    if (!isEditMode || !isAdmin) return;

    const currentIndex = sortedWidgets.findIndex(w => w.i === widgetId);
    if (currentIndex <= 0) return;

    const targetWidget = sortedWidgets[currentIndex - 1];
    const currentWidget = sortedWidgets[currentIndex];

    const newLayout = currentLayout.map(item => {
      if (item.i === widgetId) return { ...item, y: targetWidget.y };
      if (item.i === targetWidget.i) return { ...item, y: currentWidget.y };
      return item;
    });

    updateAllLayouts(newLayout);
  }, [isEditMode, isAdmin, currentLayout, sortedWidgets, updateAllLayouts]);

  // Handle move widget down
  const handleMoveDown = useCallback((widgetId: string) => {
    if (!isEditMode || !isAdmin) return;

    const currentIndex = sortedWidgets.findIndex(w => w.i === widgetId);
    if (currentIndex >= sortedWidgets.length - 1) return;

    const targetWidget = sortedWidgets[currentIndex + 1];
    const currentWidget = sortedWidgets[currentIndex];

    const newLayout = currentLayout.map(item => {
      if (item.i === widgetId) return { ...item, y: targetWidget.y };
      if (item.i === targetWidget.i) return { ...item, y: currentWidget.y };
      return item;
    });

    updateAllLayouts(newLayout);
  }, [isEditMode, isAdmin, currentLayout, sortedWidgets, updateAllLayouts]);

  // Start resize
  const handleResizeStart = useCallback((
    e: React.MouseEvent,
    widgetId: string,
    direction: ResizeDirection
  ) => {
    if (!isEditMode || !isAdmin) return;
    e.preventDefault();
    e.stopPropagation();

    const widget = currentLayout.find(w => w.i === widgetId);
    if (!widget) return;

    setResizing({
      widgetId,
      direction,
      startX: e.clientX,
      startY: e.clientY,
      startW: widget.w,
      startH: widget.h,
    });
    setSelectedWidget(widgetId);
  }, [isEditMode, isAdmin, currentLayout]);

  // Handle mouse move for resize
  useEffect(() => {
    if (!resizing) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - resizing.startX;
      const deltaY = e.clientY - resizing.startY;

      // Grid cell size (approximate)
      const gridCellWidth = 120;
      const gridCellHeight = 120;

      const config = widgetConfig[resizing.widgetId] || { minW: 1, minH: 1, maxW: 6, maxH: 4 };
      const minW = config.minW || 1;
      const minH = config.minH || 1;
      const maxW = config.maxW || 6;
      const maxH = config.maxH || 4;

      let newW = resizing.startW;
      let newH = resizing.startH;

      // Calculate width change
      if (resizing.direction?.includes('e')) {
        const wDelta = Math.round(deltaX / gridCellWidth);
        newW = Math.max(minW, Math.min(maxW, resizing.startW + wDelta));
      } else if (resizing.direction?.includes('w')) {
        const wDelta = Math.round(-deltaX / gridCellWidth);
        newW = Math.max(minW, Math.min(maxW, resizing.startW + wDelta));
      }

      // Calculate height change
      if (resizing.direction?.includes('s')) {
        const hDelta = Math.round(deltaY / gridCellHeight);
        newH = Math.max(minH, Math.min(maxH, resizing.startH + hDelta));
      } else if (resizing.direction?.includes('n')) {
        const hDelta = Math.round(-deltaY / gridCellHeight);
        newH = Math.max(minH, Math.min(maxH, resizing.startH + hDelta));
      }

      // Update layout if size changed
      if (newW !== resizing.startW || newH !== resizing.startH) {
        const newLayout = currentLayout.map(item =>
          item.i === resizing.widgetId ? { ...item, w: newW, h: newH } : item
        );
        updateAllLayouts(newLayout);
        setResizing(prev => prev ? { ...prev, startW: newW, startH: newH, startX: e.clientX, startY: e.clientY } : null);
      }
    };

    const handleMouseUp = () => {
      setResizing(null);
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [resizing, currentLayout, updateAllLayouts]);

  // Toggle widget selection
  const toggleWidgetSelection = (widgetId: string) => {
    setSelectedWidget(prev => prev === widgetId ? null : widgetId);
  };

  // Render resize handles
  const renderResizeHandles = (widgetId: string) => {
    const handles: { direction: ResizeDirection; className: string }[] = [
      // Corners
      { direction: 'nw', className: 'resize-handle corner nw' },
      { direction: 'ne', className: 'resize-handle corner ne' },
      { direction: 'sw', className: 'resize-handle corner sw' },
      { direction: 'se', className: 'resize-handle corner se' },
      // Edges
      { direction: 'n', className: 'resize-handle edge n' },
      { direction: 's', className: 'resize-handle edge s' },
      { direction: 'e', className: 'resize-handle edge e' },
      { direction: 'w', className: 'resize-handle edge w' },
    ];

    return handles.map(({ direction, className }) => (
      <div
        key={direction}
        className={`${className} ${resizing?.widgetId === widgetId ? 'active' : ''}`}
        onMouseDown={(e) => handleResizeStart(e, widgetId, direction)}
      />
    ));
  };

  // Render widget
  const renderWidget = (layoutItem: LayoutItem, index: number) => {
    const widgetInfo = widgetComponents[layoutItem.i];
    if (!widgetInfo) return null;

    const Component = widgetInfo.component;
    const isDragging = draggedWidget === layoutItem.i;
    const isSelected = selectedWidget === layoutItem.i;
    const isResizingThis = resizing?.widgetId === layoutItem.i;
    const isFirst = index === 0;
    const isLast = index === sortedWidgets.length - 1;

    return (
      <div
        key={layoutItem.i}
        className={`widget-wrapper ${isEditMode ? 'edit-mode' : ''} ${isDragging ? 'dragging' : ''} ${isSelected ? 'selected' : ''} ${isResizingThis ? 'resizing' : ''}`}
        draggable={isEditMode && isAdmin && !resizing}
        onDragStart={(e) => handleDragStart(e, layoutItem.i)}
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, layoutItem.i)}
        style={{
          gridColumn: `span ${layoutItem.w}`,
          gridRow: `span ${layoutItem.h}`,
        }}
      >
        {isEditMode && (
          <>
            {/* Drag Handle */}
            <div
              className="widget-drag-handle"
              onClick={() => toggleWidgetSelection(layoutItem.i)}
            >
              <span className="drag-icon">⋮⋮ {widgetInfo.title}</span>
              <span className="size-indicator">{layoutItem.w}×{layoutItem.h}</span>
            </div>

            {/* Quick Controls */}
            <div className="widget-controls">
              <button
                className="widget-control-btn move-btn"
                onClick={() => handleMoveUp(layoutItem.i)}
                disabled={isFirst}
                title="Move Up"
              >
                ▲
              </button>
              <button
                className="widget-control-btn move-btn"
                onClick={() => handleMoveDown(layoutItem.i)}
                disabled={isLast}
                title="Move Down"
              >
                ▼
              </button>
              <button
                className="widget-control-btn delete-btn"
                onClick={() => handleDeleteWidget(layoutItem.i)}
                title="Remove"
              >
                ✕
              </button>
            </div>

            {/* Canvas-style Resize Handles */}
            {renderResizeHandles(layoutItem.i)}
          </>
        )}
        <div className="widget-content">
          <Component />
        </div>
      </div>
    );
  };

  if (isLoading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Loading dashboard...</p>
      </div>
    );
  }

  return (
    <div className={`dashboard-container ${isEditMode ? 'editing' : ''} ${resizing ? 'is-resizing' : ''}`}>

      {/* Dashboard Header */}
      <header className="dashboard-header gap-2 md:gap-4 flex-col md:flex-row">
        <div className="header-left w-full md:w-auto flex-1">
          <h1 className="dashboard-title text-2xl sm:text-3xl md:text-4xl">
            <span className="title-icon">⚡</span>
            <span className="hidden sm:inline">{t('dashboard.title').toUpperCase()}</span>
            <span className="sm:hidden">MDB</span>
          </h1>
          <p className="dashboard-subtitle text-xs sm:text-sm md:text-base mt-1">{t('dashboard.subtitle')}</p>
        </div>

        <div className="header-right w-full md:w-auto flex flex-col sm:flex-row gap-2 md:gap-4">
          <div className="system-status-pill">
            <div className={`status-beacon ${isConnected ? 'online' : 'offline'}`}></div>
            <div className="status-text text-xs sm:text-sm">
              <span className="label block">{t('dashboard.systemStatus').toUpperCase()}</span>
              <span className={`value ${isConnected ? 'text-green' : 'text-red'}`}>
                {isConnected ? t('dashboard.operational').toUpperCase() : t('dashboard.disconnected').toUpperCase()}
              </span>
            </div>
          </div>
          <div className="time-display text-xs sm:text-sm">
            <span className="time block font-bold">{currentTime.toLocaleTimeString('th-TH', { hour12: false })}</span>
            <span className="date text-gray-500">{currentTime.toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: '2-digit' })}</span>
          </div>
        </div>
      </header>

      {/* Error Notification Layer */}
      <div className="notification-layer">
        <InfluxErrorNotification />
      </div>

      {/* Time Range Summary Panel */}
      <TimeRangeSummaryPanel />

      {/* Main Grid Layout */}
      <main className="dashboard-grid-layout" ref={containerRef}>
        {sortedWidgets.map((layoutItem, index) => renderWidget(layoutItem, index))}
      </main>

      {/* Add Widget Panel (Edit Mode Only) */}
      {isEditMode && isAdmin && hiddenWidgets.length > 0 && (
        <div className="add-widget-section">
          <button
            className="add-widget-toggle"
            onClick={() => setShowAddPanel(!showAddPanel)}
          >
            {showAddPanel ? '✕ Close' : '➕ Add Widget'}
          </button>

          {showAddPanel && (
            <div className="add-widget-panel">
              <h3>Available Widgets</h3>
              <div className="available-widgets">
                {hiddenWidgets.map(widgetId => (
                  <button
                    key={widgetId}
                    className="add-widget-item"
                    onClick={() => handleAddWidget(widgetId)}
                  >
                    <span className="widget-name">{widgetComponents[widgetId]?.title}</span>
                    <span className="add-icon">+</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Edit Mode Toggle */}
      <EditModeToggle />

      {/* Footer */}
      <footer className="dashboard-footer">
        <div className="footer-info">
          Last Update: {lastUpdate ? lastUpdate.toLocaleTimeString() : '-'}
        </div>
        <div className="footer-version">v2.9.0 (Canvas Resize)</div>
      </footer>
    </div>
  );
};

// Main component
const DashboardPage: React.FC = () => {
  return (
    <DashboardLayoutProvider>
      <InfluxProvider autoFetch={true} defaultRange="Real-time">
        <DashboardContent />
      </InfluxProvider>
    </DashboardLayoutProvider>
  );
};

export default DashboardPage;