import React, { useState } from 'react';
import './FrequencyBlock.css';
import { useWebSocket } from '../context/WebSocketContext';
import { useLanguage } from '../context/LanguageContext';
import VoltageRealtimeChart, { ViewMode } from './VoltageRealtimeChart'; // Import Chart Component
import { Zap, Wifi, WifiOff } from 'lucide-react';

const FrequencyBlock: React.FC = () => {
  const { energyData, isConnected, lastUpdate } = useWebSocket();
  const { t } = useLanguage();
  const [selectedPhase, setSelectedPhase] = useState<ViewMode | null>(null); // State สำหรับ Modal

  const asNumber = (val: any, fallback = 0): number => {
    if (typeof val === 'number' && Number.isFinite(val)) return val;
    const n = Number(val);
    return Number.isFinite(n) ? n : fallback;
  };

  const displayData = {
    f1: asNumber(energyData?.voltage?.f1, 0),
    f2: asNumber(energyData?.voltage?.f2, 0),
    f3: asNumber(energyData?.voltage?.f3, 0)
  };

  const dataAge = lastUpdate ? (Date.now() - lastUpdate.getTime()) / 1000 : 999;
  const isStale = dataAge > 5;

  const nominalVoltage = 230;
  const maxScale = 300;

  // ฟังก์ชันจัดการคลิกเลือกเฟส
  const handlePhaseClick = (phase: ViewMode) => {
    setSelectedPhase(phase);
  };

  const renderPhaseRow = (phaseName: string, value: number, colorClass: string, labelClass: string, viewMode: ViewMode) => {
    const percentage = Math.min((value / maxScale) * 100, 100);
    const nominalPercent = (nominalVoltage / maxScale) * 100;

    return (
      <div
        className="voltage-phase-row clickable"
        onClick={() => handlePhaseClick(viewMode)} // เพิ่ม Click Event
        title={`Click to analyze ${phaseName} waveform`}
      >
        <div className={`phase-badge ${labelClass}`}>
          {phaseName}
        </div>

        <div className="voltage-info-group">
          <div className="voltage-text-row">
            <span className={`voltage-value ${isStale ? 'stale' : ''}`}>
              {value.toFixed(1)}
            </span>
            <span className="voltage-unit">V</span>
          </div>

          <div className="voltage-bar-container">
            <div
              className={`voltage-bar-fill ${colorClass}`}
              style={{ width: `${percentage}%` }}
            ></div>
            <div
              className="nominal-marker"
              style={{ left: `${nominalPercent}%` }}
              title="Nominal 230V"
            ></div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <>
      <div className="frequency-block-component modern-voltage-card">
        <div className="card-header">
          <div className="header-title-group">
            <div className="icon-box"><Zap size={20} /></div>
            <span className="title-text">{t('power.voltage').toUpperCase()}</span>
          </div>
          <div className={`status-pill ${isConnected && !isStale ? 'online' : 'offline'}`}>
            <div className="status-dot"></div>
            {isConnected ? (
              <>
                {isStale ? <WifiOff size={14} /> : <Wifi size={14} />}
                <span>{isStale ? 'Waiting' : 'Real-time'}</span>
              </>
            ) : (
              <>
                <WifiOff size={14} />
                <span>Offline</span>
              </>
            )}
          </div>
        </div>

        <div className="voltage-content-container">
          {renderPhaseRow('L1', displayData.f1, 'fill-red', 'badge-red', 'phase1')}
          {renderPhaseRow('L2', displayData.f2, 'fill-yellow', 'badge-yellow', 'phase2')}
          {renderPhaseRow('L3', displayData.f3, 'fill-blue', 'badge-blue', 'phase3')}
        </div>

        <div className="card-footer-info">
          <span>Nominal: {nominalVoltage}V</span>
          <span>Max: {maxScale}V</span>
          <span className="hint-text">(Click rows for graph)</span>
        </div>
      </div>

      {/* Modal Popup for Chart */}
      {selectedPhase && (
        <div className="modal-backdrop" onClick={() => setSelectedPhase(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <VoltageRealtimeChart
              initialViewMode={selectedPhase}
              onClose={() => setSelectedPhase(null)}
              isPopup={true}
            />
          </div>
        </div>
      )}
    </>
  );
};

export default FrequencyBlock;