export const BUILD_VERSION = process.env.REACT_APP_BUILD_VERSION || 'dev';
export const BUILD_ISO = process.env.REACT_APP_BUILD_ISO || '';

export function versioned(url: string): string {
  if (!url) return url;
  const sep = url.includes('?') ? '&' : '?';
  return `${url}${sep}v=${BUILD_VERSION}`;
}
